CREATE TABLE IF NOT EXISTS pm_profiles(
 project_id TEXT PRIMARY KEY REFERENCES projects(id), reference TEXT NOT NULL UNIQUE COLLATE NOCASE,
 stage TEXT NOT NULL DEFAULT 'initiation' CHECK(stage IN ('initiation','planning','delivery','transition','closure','closed')),
 manager_id TEXT NOT NULL REFERENCES users(id), sponsor_id TEXT REFERENCES users(id),
 contract_id TEXT REFERENCES managed_contracts(id), data TEXT NOT NULL DEFAULT '{}',
 revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS pm_members(project_id TEXT NOT NULL REFERENCES projects(id),user_id TEXT NOT NULL REFERENCES users(id),responsibility TEXT NOT NULL,PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS pm_controls(project_id TEXT NOT NULL REFERENCES projects(id),code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'not_started',owner_id TEXT REFERENCES users(id),evidence TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,code));
CREATE TABLE IF NOT EXISTS pm_task_links(task_id TEXT PRIMARY KEY REFERENCES work_tasks(id),project_id TEXT NOT NULL REFERENCES projects(id),data TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS pm_task_project ON pm_task_links(project_id);
CREATE TABLE IF NOT EXISTS pm_records(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL CHECK(kind IN ('risk','issue','change','milestone','stakeholder','procurement','quality','handover','lesson','cost','benefit')),data TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pm_record_project ON pm_records(project_id,kind);
CREATE TABLE IF NOT EXISTS pm_links(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),source_type TEXT NOT NULL,source_id TEXT NOT NULL,UNIQUE(project_id,source_type,source_id));
CREATE TABLE IF NOT EXISTS pm_gate_requests(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),stage TEXT NOT NULL,revision INTEGER NOT NULL,requested_by TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending',decided_by TEXT REFERENCES users(id),decision_note TEXT,evidence_snapshot TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS pm_pending_gate ON pm_gate_requests(project_id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS pm_time_entries(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),task_id TEXT REFERENCES work_tasks(id),user_id TEXT NOT NULL REFERENCES users(id),work_date TEXT NOT NULL,hours_units INTEGER NOT NULL CHECK(hours_units>0 AND hours_units<=2400),billable INTEGER NOT NULL DEFAULT 0,sla_entry_id TEXT REFERENCES contract_entries(id),notes TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted',decided_by TEXT REFERENCES users(id),decision_note TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,decided_at TEXT);
CREATE TABLE IF NOT EXISTS pm_audit(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS pm_audit_project ON pm_audit(project_id,created_at);
CREATE TABLE IF NOT EXISTS pm_alerts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),rule TEXT NOT NULL,entity_id TEXT NOT NULL,message TEXT NOT NULL,severity TEXT NOT NULL DEFAULT 'medium',status TEXT NOT NULL DEFAULT 'open',acknowledged_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(project_id,rule,entity_id));
CREATE TABLE IF NOT EXISTS pm_notifications(alert_id TEXT NOT NULL REFERENCES pm_alerts(id),user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'available',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(alert_id,user_id));
CREATE TABLE IF NOT EXISTS pm_scan_runs(id TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'running',evaluated INTEGER NOT NULL DEFAULT 0,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS pm_write_guards(project_id TEXT PRIMARY KEY,expected_revision INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS pm_guard_revision BEFORE INSERT ON pm_write_guards WHEN NOT EXISTS(SELECT 1 FROM pm_profiles WHERE project_id=NEW.project_id AND revision=NEW.expected_revision) BEGIN SELECT RAISE(ABORT,'PM revision conflict'); END;
CREATE TRIGGER IF NOT EXISTS pm_daily_hours BEFORE INSERT ON pm_time_entries WHEN NEW.status='submitted' AND NEW.hours_units+COALESCE((SELECT SUM(hours_units) FROM pm_time_entries WHERE user_id=NEW.user_id AND work_date=NEW.work_date AND status IN ('submitted','approved')),0)>2400 BEGIN SELECT RAISE(ABORT,'PM daily hours exceeded'); END;
CREATE TRIGGER IF NOT EXISTS pm_sla_hours BEFORE INSERT ON sla_time_entries WHEN NEW.id LIKE 'pm-%' AND NEW.status='recorded' AND (COALESCE((SELECT CAST(ROUND(CAST(json_extract(data,'$.hours_sold') AS REAL)*100) AS INTEGER) FROM contract_entries WHERE id=NEW.sla_entry_id),0)<NEW.hours_units+COALESCE((SELECT SUM(hours_units) FROM sla_time_entries WHERE sla_entry_id=NEW.sla_entry_id AND status='recorded'),0)) BEGIN SELECT RAISE(ABORT,'PM SLA hours exceeded'); END;
CREATE TRIGGER IF NOT EXISTS pm_task_dependency_guard BEFORE UPDATE OF status ON work_tasks WHEN NEW.status IN ('in_progress','done') AND EXISTS(SELECT 1 FROM pm_task_links l,json_each(l.data,'$.dependencies') d LEFT JOIN work_tasks predecessor ON predecessor.id=d.value WHERE l.task_id=NEW.id AND COALESCE(predecessor.status,'missing')<>'done') BEGIN SELECT RAISE(ABORT,'PM predecessor incomplete'); END;
CREATE TRIGGER IF NOT EXISTS pm_task_source_update AFTER UPDATE ON work_tasks WHEN (OLD.title IS NOT NEW.title OR OLD.description IS NOT NEW.description OR OLD.assignee_id IS NOT NEW.assignee_id OR OLD.priority IS NOT NEW.priority OR OLD.status IS NOT NEW.status OR OLD.due_date IS NOT NEW.due_date) AND EXISTS(SELECT 1 FROM pm_task_links WHERE task_id=NEW.id) BEGIN UPDATE pm_profiles SET revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE project_id=(SELECT project_id FROM pm_task_links WHERE task_id=NEW.id); INSERT INTO pm_audit(id,project_id,action,snapshot) SELECT lower(hex(randomblob(16))),project_id,'Linked task source updated',json_object('task_id',NEW.id,'before',json_object('title',OLD.title,'status',OLD.status,'due_date',OLD.due_date,'assignee_id',OLD.assignee_id),'after',json_object('title',NEW.title,'status',NEW.status,'due_date',NEW.due_date,'assignee_id',NEW.assignee_id)) FROM pm_task_links WHERE task_id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS pm_task_alert_owner BEFORE INSERT ON workflow_alerts WHEN NEW.entity_type='task' AND NEW.rule IN ('unassigned_task','overdue_task') AND EXISTS(SELECT 1 FROM pm_task_links WHERE task_id=NEW.entity_id) BEGIN SELECT RAISE(IGNORE); END;
